package org.apache.commons.text.similarity;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class LongestCommonSubsequence_ESTest_test05 extends LongestCommonSubsequence_ESTest_scaffolding {

    /**
     * A freshly allocated CharBuffer is filled entirely with the NUL character
     * ('�'). The input "�r" therefore shares exactly one character
     * with the buffer (its leading NUL), so the longest common subsequence
     * between them has length 1.
     */
    @Test(timeout = 4000)
    public void apply_sharesSingleNulCharWithNulFilledBuffer_returnsLengthOne() throws Throwable {
        LongestCommonSubsequence lcs = new LongestCommonSubsequence();
        CharBuffer nulFilledBuffer = CharBuffer.allocate(3226);

        Integer lcsLength = lcs.apply((CharSequence) "�r", (CharSequence) nulFilledBuffer);

        assertEquals(1, (int) lcsLength);
    }
}
